"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[8631],{28631:a=>{a.exports=JSON.parse('{"meta":{"title":"Muslim Companion Alexa Becerisi: Echo\'nuzda Ezan - iMuslim Life","description":"Muslim Companion, Amazon Echo\'nuzda namaz vakitlerinizde ezan\u0131 okur; Kur\'an, zikirler, H\u0131fz Ko\xe7u ve Ramazan modu da var. \xdccretsiz. Kurulum alexa.imuslimlife.com adresinde."},"hero":{"title":"Alexa i\xe7in Muslim Companion","lede":"Yerel namaz vakitlerinizde ezan, namaz sonras\u0131 zikirler, Kur\'an tilaveti ve camiinizden hat\u0131rlatmalar, Amazon Echo\'nuzda.","live":"\u2714 Alexa\'da yay\u0131nda","dashboard":"Paneli A\xe7","tryWeb":"Web Uygulamas\u0131n\u0131 Dene","imgAlt":"Amazon Alexa cihaz\u0131","athan":"\\"Allahu Ekber...\\"","maghrib":"Ak\u015fam 19.45\'te"},"how":{"h2":"Nas\u0131l \xc7al\u0131\u015f\u0131r","sub":"Ki\u015fisel m\xfcezzininizi \xfc\xe7 basit ad\u0131mda, be\u015f dakikadan k\u0131sa s\xfcrede kurun.","s1":{"h3":"Beceriyi Etkinle\u015ftirin","p":"Telefonunuzda Alexa uygulamas\u0131n\u0131 a\xe7\u0131n, <b>Muslim Companion</b>\'\u0131 aray\u0131n ve <i>Enable to Use</i>\'a dokunun. Ard\u0131ndan onaylamak i\xe7in \u0130ngilizce \\"<q>{{p1}}</q>\\" (Alexa, Muslim Companion\'\u0131 a\xe7) deyin."},"s2":{"h3":"Giri\u015f Yap\u0131n ve Ayarlay\u0131n","p":"<a>alexa.imuslimlife.com</a> adresine gidin, giri\u015f yap\u0131n, konumunuzu onaylay\u0131n, ezan sesini se\xe7in ve kamet ile cuma hat\u0131rlatmalar\u0131 i\xe7in camiinizi (\xf6rne\u011fin AMCC) takip edin.","voice":"<b>Ya da sesle:</b> \\"<q>{{p1}}</q>\\" (hesaplama y\xf6ntemini ISNA yap) ve \\"<q>{{p2}}</q>\\" (mezhebi Hanefi yap); panele gerek yok. A\u015fa\u011f\u0131daki sesli komutlara bak\u0131n."},"s3":{"h3":"Rutin Olu\u015fturun ve Keyfini \xc7\u0131kar\u0131n","p":"Alexa uygulamas\u0131nda bir rutin olu\u015fturun: <i>Muslim Companion Azan</i> sens\xf6r\xfc a\xe7\u0131ld\u0131\u011f\u0131nda <i>Muslim Companion</i>\'\u0131 a\xe7. Echo\'nuz art\u0131k her namaz vaktinde ezan\u0131 otomatik okur. <a>Ad\u0131m ad\u0131m kurulum k\u0131lavuzumuz</a> ekran g\xf6r\xfcnt\xfcleriyle size yol g\xf6sterir."}},"features":{"h2":"\xd6ne \xc7\u0131kan \xd6zellikler","sub":"Her \u015fey alexa.imuslimlife.com\'da ayarlan\u0131r ve her ek \xf6zellik siz a\xe7ana kadar kapal\u0131 kal\u0131r","soon":"Yak\u0131nda: \xe2lim incelemesi","items":{"athan":{"title":"Namaz vakitlerinizde ezan","description":"Echo\'nuz be\u015f vakit i\xe7in yerel saatinizde ezan\u0131 okur; m\xfcezzin sesi se\xe7ene\u011fi ve \xf6zel bir sabah ezan\u0131 da var."},"masjid":{"title":"Masjid Connect","description":"Camiinizi (AMCC gibi) takip edin, her kametten ve cumadan \xf6nce camiinizin yay\u0131mlad\u0131\u011f\u0131 saatlerle hat\u0131rlatma al\u0131n."},"quran":{"title":"Kur\'an tilaveti","description":"30\'dan fazla tan\u0131nm\u0131\u015f k\xe2ri. Ezandan sonra bir sure ya da g\xfcn boyu Kur\'an; kald\u0131\u011f\u0131n\u0131z yerden devam edin."},"adhkar":{"title":"Namaz sonras\u0131 zikirler","description":"Her namazdan sonra Ayetel K\xfcrsi ve \xfc\xe7 Kul suresi; Arap\xe7a metin ve \u0130ngilizce ya da Urduca meal ile. Siz a\xe7ana kadar kapal\u0131."},"hifz":{"title":"H\u0131fz Ko\xe7u","description":"Echo\'nuzda birka\xe7 ayeti birden ezberleyin: her ayet \xfc\xe7 kez, sonra t\xfcm ders birlikte; ilerlemeniz kaydedilir. \u0130nternette de \xe7al\u0131\u015f\u0131n."},"ramadan":{"title":"Ramazan modu","description":"Sabahtan \xf6nce sahur hat\u0131rlatmas\u0131, ak\u015famda iftar duyurusu ve yats\u0131dan sonra Mekke teravih tilaveti."},"show":{"title":"Echo Show ekran\u0131","description":"Bug\xfcn\xfcn namaz vakitleri ekranda, s\u0131radaki namaz vurgulu ve geri say\u0131ml\u0131; ayr\u0131ca her zaman a\xe7\u0131k Namaz Vakitleri widget\'\u0131."},"scenes":{"title":"Ev Sahneleri","description":"Ezanda \u0131\u015f\u0131klar\u0131 k\u0131s\u0131n, sabahtan \xf6nce yumu\u015fak\xe7a uyan\u0131n ya da yats\u0131dan sonra sakin bir ak\u015fam kurun; kendi Alexa rutinlerinizle."},"duas":{"title":"Ezan sonras\u0131 dualar","description":"Ezan duas\u0131 ve se\xe7ti\u011finiz dualar, ezandan hemen sonra Echo\'nuzda."},"qibla":{"title":"K\u0131ble y\xf6n\xfc","description":"K\u0131blenin nerede oldu\u011funu sorun: evinizden y\xf6n\xfc derece ve pusula y\xf6n\xfc olarak, ayr\u0131ca Mekke\'nin uzakl\u0131\u011f\u0131."},"hijri":{"title":"Hicri tarih ve \u0130slami takvim","description":"Bug\xfcn\xfcn Hicri tarihi ve Ramazan\'a, Bayram\'a, A\u015fure\'ye, Arefe\'ye ya da eyyam-\u0131 b\xeez\'e ka\xe7 g\xfcn kald\u0131\u011f\u0131. Namaz vakitlerinizle ayn\u0131 tarihler."},"fasting":{"title":"S\xfcnnet oru\xe7lar","description":"S\u0131radaki s\xfcnnet orucun ne zaman oldu\u011funu sorun ya da pazartesi, per\u015fembe, eyyam-\u0131 b\xeez, Arefe ve A\u015fure\'den \xf6nceki ak\u015fam yats\u0131dan sonra hat\u0131rlatma al\u0131n."},"tasbih":{"title":"Tesbih ve sabah-ak\u015fam zikirleri","description":"Alexa zikri sizinle sayar (namazdan sonra 33, 33, 34), Echo Show\'da dokunmatik saya\xe7la, ve sabah-ak\u015fam zikirlerini okur."},"translation":{"title":"Mealli Kur\'an","description":"Herhangi bir sureyi sesle a\xe7\u0131n, her ayetten sonra \u0130ngilizce ya da Urduca meal ile; her cuma Kehf suresi."},"daily":{"title":"G\xfcnl\xfck Dua, Hadis ve Esma\xfc\'l-H\xfcsna","description":"Her g\xfcn k\u0131sa bir dua, hadis ya da 99 isimden biri, kayna\u011f\u0131yla birlikte; yay\u0131mlanmadan \xf6nce bir \xe2lim inceler."}}},"screens":{"h2":"\u0130\u015f ba\u015f\u0131nda g\xf6r\xfcn","sub":"Florida\'da AMCC\'yi takip eden bir ailenin ger\xe7ek ekranlar\u0131: kendi konumlar\u0131n\u0131n namaz vakitleri ve caminin yay\u0131mlad\u0131\u011f\u0131 kamet saatleri.","showAlt":"Echo Show ekran\u0131: caminin kamet saatleriyle bug\xfcn\xfcn namaz vakitleri, s\u0131radaki namaz ak\u015fam geri say\u0131mla vurgulu","showH":"Echo Show\'unuzda","showP":"\\"<q>{{p1}}</q>\\" (Muslim Companion\'a bug\xfcn\xfcn namaz vakitlerini sor) deyin: be\u015f vakit ve g\xfcne\u015f do\u011fu\u015fu, her birinin yan\u0131nda camiinizin kameti, s\u0131radaki namaz geri say\u0131mla vurgulu.","phoneAlt":"Telefonda Camim: cami, bug\xfcn\xfcn ezan ve kamet saatleri, cuma ve Echo hat\u0131rlatma se\xe7enekleri","phoneH":"Telefonunuzda","phoneP":"<a>alexa.imuslimlife.com</a> adresinde <b>Camim</b>\'i a\xe7\u0131n ve camiinizi se\xe7in. Bug\xfcn\xfcn ezan ve kamet saatlerini ve bu cuman\u0131n vaktini g\xf6r\xfcrs\xfcn\xfcz; Echo\'nun kamet ve cumadan ne kadar \xf6nce hat\u0131rlataca\u011f\u0131n\u0131 se\xe7ersiniz.","widgetAlt":"Namaz Vakitleri widget\'\u0131: s\u0131radaki namaz ak\u015fam geri say\u0131mla, kamet saati ve bug\xfcn\xfcn be\u015f vakti","widgetH":"Her zaman a\xe7\u0131k widget","widgetP":"Echo Show 8, 10 ve 15\'te <b>Namaz Vakitleri</b> widget\'\u0131n\u0131 ekleyin: s\u0131radaki namaz, geri say\u0131m\u0131 ve camiinizin kameti ana ekranda kal\u0131r."},"voice":{"h2":"Sesli Komutlar","sub":"Muslim Companion\'a s\xf6yleyebilece\u011finiz her \u015fey, \xf6zelli\u011fe g\xf6re gruplanm\u0131\u015f. Bir yapay zek\xe2 asistan\u0131 m\u0131 kullan\u0131yorsunuz? <a>Onu namaz vakitlerimize ba\u011flay\u0131n</a>."},"ref":{"langsTitle":"Diller ve \xfclkeler","langsBody":"Muslim Companion <b>\u0130ngilizce</b>, <b>Arap\xe7a</b> (\\"\u0627\u0644\u0631\u0641\u064a\u0642 \u0627\u0644\u0645\u0633\u0644\u0645\\") ve <b>Hint\xe7e</b> (\\"\u092e\u0941\u0938\u094d\u0932\u093f\u092e \u0915\u092e\u094d\u092a\u0948\u0928\u093f\u092f\u0928\\") anlar. \u0130ngilizcede c\xfcmleleri tam yaz\u0131ld\u0131\u011f\u0131 gibi, \\"<q>{{p1}}</q>\\" ile ba\u015flayarak s\xf6yleyin (ad <b>ABD, Kanada, Birle\u015fik Krall\u0131k, Hindistan ve Avustralya</b>\'da ayn\u0131d\u0131r). Arap\xe7a ya da Hint\xe7e c\xfcmleleri g\xf6rmek i\xe7in yukar\u0131dan bir dil se\xe7in. Bir c\xfcmlede se\xe7enek varsa, \xf6rne\u011fin hesaplama y\xf6ntemi, a\xe7\u0131klama s\xf6yleyebilece\u011finiz t\xfcm se\xe7enekleri listeler.","soonNote":"<b>Yak\u0131nda</b> i\u015faretli komutlar hen\xfcz kullan\u0131lam\u0131yor; rozet nedenini s\xf6yler.","english":"English","soonSuffix":" \xb7 yak\u0131nda","langNote":"<b>{{title}}</b>: Muslim Companion\'\u0131 bu dilde kullanmak i\xe7in Alexa dilini {{lang}} olarak ayarlay\u0131n. Becerinin bu dildeki ad\u0131 <n>{{name}}</n>. Anlad\u0131\u011f\u0131 c\xfcmleler tam olarak bunlard\u0131r; a\xe7\u0131klamalar \u0130ngilizce kal\u0131r.","langAr":"Arap\xe7a (Suudi Arabistan)","langHi":"Hint\xe7e (Hindistan)","all":"T\xfcm\xfc","comingSoon":"Yak\u0131nda","showsOnShow":"Echo Show\'da g\xf6r\xfcn\xfcr","whilePlaying":"Muslim Companion \xe7alarken","turnsOff":"Otomatik ezan\u0131 kapat\u0131r","tip":"\u0130pucu: {{tip}}","footer":"\\"<q>{{p1}}</q>\\" (Alexa, Muslim Companion\'\u0131 a\xe7) diyerek ba\u015flay\u0131p sonra da sorabilirsiniz. \\"<q>next</q>\\" (sonraki), \\"<q>pause</q>\\" (duraklat) ve \\"<q>stop</q>\\" (durdur) gibi komutlar Muslim Companion \xe7alarken \xe7al\u0131\u015f\u0131r."},"api":{"h2":"Denenmi\u015f API\'mizle \xc7al\u0131\u015f\u0131r","p":"Muslim Companion Alexa becerisi, tam konumunuza g\xf6re hassas hesaplamalar yapan g\xfc\xe7l\xfc namaz vakitleri API\'miz \xfczerine kuruludur.","methods":{"primary":"23 Hesaplama Y\xf6ntemi + Hanefi veya Standart \u0130kindi","secondary":"ISNA, D\xfcnya M\xfcsl\xfcman Birli\u011fi, \xdcmm\xfc\'l-Kur\xe2, M\u0131s\u0131r, Kara\xe7i, K\xf6rfez, Kuveyt, Katar, Singapur, Fransa, T\xfcrkiye, Rusya, Tahran ve Caferi; panelden ya da sesle ayarlan\u0131r"},"hijri":{"primary":"Hicri Takvim Entegrasyonu","secondary":"Namaz vakitlerinin yan\u0131nda do\u011fru \u0130slami tarihler"},"perf":{"primary":"Y\xfcksek Performans","secondary":"H\u0131z ve g\xfcvenilirlik i\xe7in optimize edildi"},"free":{"primary":"Topluluk \u0130\xe7in \xdccretsiz","secondary":"Namaz vakitleri API\'si \xfccretsizdir"},"cta":"API\'mizi Ke\u015ffedin","imgAlt":"API \xe7izimi"},"cta":{"h2":"Ezan\u0131 Alexa\'dan duymaya haz\u0131r m\u0131s\u0131n\u0131z?","p":"Beceri yay\u0131nda. Ki\u015fisel namaz program\u0131n\u0131z\u0131 be\u015f dakikadan k\u0131sa s\xfcrede kurun.","guide":"Kurulum K\u0131lavuzunu G\xf6r","small":"Her zaman \xfccretsiz \xb7 Uygulama indirmeye gerek yok \xb7 T\xfcm Echo cihazlar\u0131yla \xe7al\u0131\u015f\u0131r"},"faq":{"h2":"S\u0131k Sorulan Sorular","devices":{"q":"Bu beceri hangi Alexa cihazlar\u0131yla \xe7al\u0131\u015f\u0131r?","a":"Muslim Companion becerisi t\xfcm Amazon Echo ve Alexa destekli cihazlarla \xe7al\u0131\u015f\u0131r. En iyi ses i\xe7in Echo, Echo Dot veya Echo Show gibi kaliteli hoparl\xf6rl\xfc cihazlar\u0131 \xf6neririz."},"dst":{"q":"Beceri yaz saatine otomatik uyum sa\u011flar m\u0131?","a":"Evet, beceri namaz vakitlerini konumunuzun saat dilimine ve yaz saati de\u011fi\u015fikliklerine g\xf6re otomatik ayarlar. Hi\xe7bir elle ayar yapmadan her zaman do\u011fru vakitleri al\u0131rs\u0131n\u0131z."},"choose":{"q":"Hangi namazlarda ezan okunaca\u011f\u0131n\u0131 se\xe7ebilir miyim?","a":"Elbette! Hangi vakitlerde ezan okunaca\u011f\u0131n\u0131 siz se\xe7ersiniz; \xf6rne\u011fin yaln\u0131zca sabah, ak\u015fam ve yats\u0131 ya da be\u015f vaktin tamam\u0131. Bunu alexa.imuslimlife.com\'daki Namaz Ayarlar\u0131 sayfas\u0131nda se\xe7ersiniz."},"cost":{"q":"Bu beceri \xfccretli mi?","a":"Muslim Companion becerisi tamamen \xfccretsizdir. Temel i\u015flevler, yani do\u011fru namaz vakitleri ve otomatik ezan, M\xfcsl\xfcman topluluk i\xe7in her zaman \xfccretsiz kalacak."},"offline":{"q":"\u0130nternet ba\u011flant\u0131m kesilirse ne olur?","a":"Namaz vakitleriniz \xf6nceden hesaplan\u0131r, ancak Echo\'nuzun ezan\u0131 okumas\u0131 i\xe7in internet gerekir. Namaz vaktinde ba\u011flant\u0131 yoksa o ezan ka\xe7abilir; ba\u011flant\u0131 gelince her \u015fey otomatik devam eder."}}}')}}]);